// 老内核（Chromium < 105，如奇安信可信浏览器）不支持 :has() 选择器：
// styles/index.scss 里详情页「整页滚动」规则组全部失效，退化为表单区内滚，
// 底部块（宗地信息 / 证书管理 / Tabs）被裁掉（zentao bug 6279）。
// 探测失败时给 <html> 打 .no-has-support，由 index.scss 用普通类选择器兜底；
// 现代浏览器不会带该标记，:has() 规则行为不变。
let supportsHasSelector = false
try {
  supportsHasSelector =
    typeof CSS !== 'undefined' &&
    typeof CSS.supports === 'function' &&
    CSS.supports('selector(:has(*))')
} catch (e) {
  // selector() 参数解析异常 = 引擎不认识 :has()，视同不支持
  supportsHasSelector = false
}
if (!supportsHasSelector) {
  document.documentElement.classList.add('no-has-support')
}

// 保存到全局，方便在动态创建的组件中使用
